using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
class BoostPrincessVoice{
 static void Main(){string root="D:/WORK/Cet6Story",backup=Path.Combine(root,".git","audio-backups","princess-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));var json=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};foreach(string chapter in Directory.GetFiles(Path.Combine(root,"chapters"),"*.json")){var doc=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(chapter));object obj;if(!doc.TryGetValue("lines",out obj)||!doc.ContainsKey("audio"))continue;var lines=((System.Collections.IEnumerable)obj).Cast<Dictionary<string,object>>().Where(l=>l.ContainsKey("speaker")&&new[]{"莉瑟","公主"}.Contains(l["speaker"].ToString())).ToArray();if(lines.Length==0)continue;string relative="chapters/"+doc["audio"],path=Path.Combine(root,relative);byte[] original=File.ReadAllBytes(path),data=(byte[])original.Clone();int offset=12,start=0,length=0,rate=0,channels=0,bits=0,format=0;while(offset+8<=data.Length){string tag=System.Text.Encoding.ASCII.GetString(data,offset,4);int size=BitConverter.ToInt32(data,offset+4);if(tag=="fmt "){format=BitConverter.ToInt16(data,offset+8);channels=BitConverter.ToInt16(data,offset+10);rate=BitConverter.ToInt32(data,offset+12);bits=BitConverter.ToInt16(data,offset+22);}if(tag=="data"){start=offset+8;length=size;break;}offset+=8+size+(size%2);}if(format!=1||bits!=16||start==0)throw new Exception("unsupported PCM");var affected=new bool[length/2];double before=0,after=0;int peak=0,count=0;foreach(var line in lines){int a=(int)Math.Round(Convert.ToDouble(line["start"])*rate)*channels,b=Math.Min(length/2,(int)Math.Round(Convert.ToDouble(line["end"])*rate)*channels);for(int i=a;i<b;i++){if(affected[i])continue;affected[i]=true;int at=start+i*2;short sample=BitConverter.ToInt16(original,at);double value=sample*1.413,abs=Math.Abs(value);if(abs>28000)value=Math.Sign(value)*(28000+4767*(1-Math.Exp(-(abs-28000)/4767)));short scaled=(short)Math.Round(value);data[at]=(byte)scaled;data[at+1]=(byte)(scaled>>8);before+=(double)sample*sample;after+=(double)scaled*scaled;peak=Math.Max(peak,Math.Abs((int)scaled));count++;}}for(int i=0;i<length/2;i++)if(!affected[i]&&(data[start+i*2]!=original[start+i*2]||data[start+i*2+1]!=original[start+i*2+1]))throw new Exception("other voices changed");string destination=Path.Combine(backup,relative);Directory.CreateDirectory(Path.GetDirectoryName(destination));File.WriteAllBytes(destination,original);File.WriteAllBytes(path,data);Console.WriteLine(Path.GetFileName(chapter)+": "+lines.Length+" lines, +"+(10*Math.Log10(after/before)).ToString("F2")+" dB, peak "+peak+"; timing/other voices unchanged");}Console.WriteLine("Backup: "+backup);}
}
